"""Generate icons.js (inline-SVG injector) from design/icons/*.svg."""
import json
import re
from pathlib import Path

root = Path(__file__).resolve().parent.parent
icons = {}
for f in sorted((root / "icons").glob("*.svg")):
    body = re.search(r"<svg[^>]*>(.*)</svg>", f.read_text(), re.S).group(1)
    icons[f.stem] = re.sub(r"\s+", " ", body).strip()

js = (
    "// Generated by build-icons.py from design/icons/*.svg (Tabler Icons, MIT).\n"
    f"const ICONS = {json.dumps(icons, ensure_ascii=False, indent=1)};\n"
    "document.querySelectorAll('[data-ic]').forEach(function (el) {\n"
    "  el.innerHTML = '<svg viewBox=\"0 0 24 24\">' + ICONS[el.dataset.ic] + '</svg>';\n"
    "});\n"
)
(root / "shared" / "icons.js").write_text(js)
